class Solution:
    def nthUglyNumber(self, n: int) -> int:
        vals = set()
        a = 1
        while a <= 2**31:
            b = a
            while b <= 2**31:
                c = b
                while c <= 2**31:
                    vals.add(c)
                    c *= 5
                b *= 3
            a *= 2
        return sorted(vals)[n - 1]

solutions.better:
class Solution:
    def nthUglyNumber(self, n: int) -> int:
        import heapq
        heap = [1]
        seen = {1}
        cur = 1
        for _ in range(n):
            cur = heapq.heappop(heap)
            for p in (2, 3, 5):
                nxt = cur * p
                if nxt not in seen:
                    seen.add(nxt)
                    heapq.heappush(heap, nxt)
        return cur

